package org.congcong.proxyworker.protocol.tlssni;
import io.netty.buffer.ByteBuf; import io.netty.channel.*; import io.netty.handler.codec.ByteToMessageDecoder; import org.congcong.common.enums.ProtocolType; import org.congcong.proxyworker.config.InboundConfig; import org.congcong.proxyworker.config.UserConfig; import org.congcong.proxyworker.server.netty.ChannelAttributes; import org.congcong.proxyworker.server.tunnel.ProxyTunnelRequest; import java.nio.charset.StandardCharsets; import java.util.List;
public class TlsSniHandler extends ByteToMessageDecoder {
 private static final int MAX=32768;
 protected void decode(ChannelHandlerContext ctx, ByteBuf in, List<Object> out){ if(in.readableBytes()>MAX){ctx.close();return;} int r=in.readerIndex(); if(in.readableBytes()<5)return; int typ=in.getUnsignedByte(r), ver=in.getUnsignedShort(r+1), len=in.getUnsignedShort(r+3); if(typ!=22 || ver<0x0301 || len>MAX || in.readableBytes()<5+len)return; int p=r+5; if(in.getUnsignedByte(p)!=1){ctx.close();return;} int hsLen=((in.getUnsignedByte(p+1)&255)<<16)|((in.getUnsignedByte(p+2)&255)<<8)|(in.getUnsignedByte(p+3)&255); if(hsLen+4>len){ctx.close();return;} String sni=parseSni(in,p+4,hsLen); if(sni==null){ctx.close();return;} ByteBuf payload=in.readRetainedSlice(5+len); InboundConfig cfg=ChannelAttributes.getInboundConfig(ctx.channel()); UserConfig user=cfg.getAnonymousUser(); if(user==null){payload.release();ctx.close();return;} ProxyTunnelRequest req=new ProxyTunnelRequest(ProtocolType.TLS_SNI_TCP,sni,443,user,cfg,payload); ChannelAttributes.setProxyTunnelRequest(ctx.channel(),req); ChannelAttributes.getProxyContext(ctx.channel()).setUserId(user.getId()); ChannelAttributes.getProxyContext(ctx.channel()).setUserName(user.getUsername()); ctx.pipeline().remove(this); ctx.fireChannelRead(req); }
 private String parseSni(ByteBuf b,int p,int n){int end=p+n; if(p+2>end)return null; p+=2; if(p+32>end)return null; p+=32; if(p>=end)return null; int sid=b.getUnsignedByte(p++); p+=sid; if(p+2>end)return null; int cs=b.getUnsignedShort(p);p+=2+cs; if(p>=end)return null; int comp=b.getUnsignedByte(p++);p+=comp; if(p+2>end)return null; int extLen=b.getUnsignedShort(p);p+=2; int extEnd=Math.min(end,p+extLen); while(p+4<=extEnd){int t=b.getUnsignedShort(p), l=b.getUnsignedShort(p+2);p+=4;if(p+l>extEnd)break;if(t==0){if(l<5)return null;int q=p+2;if(q>=p+l)return null;int nameType=b.getUnsignedByte(q++);if(nameType!=0 || q+2>p+l)return null;int nameLen=b.getUnsignedShort(q);q+=2;if(q+nameLen>p+l)return null;return b.toString(q,nameLen,StandardCharsets.US_ASCII);}p+=l;} return null; }
}
